<?php $beRoot=base_url('store/'.$settings->store_slug);$beOrdersOnly=!empty($be_orders_only);$beFirst=explode(' ',trim($customer->customer_name ?? ''))[0] ?: 'there'; ?>
<main class="be-commerce be-account-page be-shell">
<nav class="be-crumbs" aria-label="Breadcrumb"><a href="<?= $beRoot; ?>">Home</a><span>/</span><a href="<?= $beRoot.'/account'; ?>">Your account</a><?php if($beOrdersOnly): ?><span>/</span><span>Orders</span><?php endif; ?></nav>
<header class="be-page-heading"><div><span class="be-eyebrow"><?= $beCopy('account_eyebrow'); ?></span><h1><?= $beOrdersOnly?$beCopy('orders_heading'):'Hello, '.htmlspecialchars($beFirst).'.'; ?></h1><p><?= $beOrdersOnly?$beCopy('orders_intro'):$beCopy('account_intro'); ?></p></div><a class="be-textlink" href="<?= $beRoot.'/products'; ?>"><?= $beCopy('account_new'); ?> ↗</a></header>
<div class="be-account-layout"><aside class="be-account-sidebar"><div class="be-profile-card"><span class="be-profile-initial"><?= htmlspecialchars(mb_strtoupper(mb_substr($customer->customer_name ?? 'C',0,1))); ?></span><h2><?= htmlspecialchars($customer->customer_name ?? 'Customer'); ?></h2><?php if(!empty($customer->email)): ?><p><?= htmlspecialchars($customer->email); ?></p><?php endif; ?><p><?= htmlspecialchars($customer->mobile ?? ''); ?></p></div><nav aria-label="Account navigation"><a href="<?= $beRoot.'/account'; ?>" <?= !$beOrdersOnly?'aria-current="page"':''; ?>>Overview <span>↗</span></a><a href="<?= $beRoot.'/account/orders'; ?>" <?= $beOrdersOnly?'aria-current="page"':''; ?>>My orders <span>↗</span></a><a href="<?= $beRoot.'/track'; ?>">Track an order <span>↗</span></a><a href="<?= $beRoot.'/account/logout'; ?>">Sign out <span>↗</span></a></nav></aside>
<div class="be-account-content"><section class="be-account-card"><div class="be-account-card-title"><div><span class="be-eyebrow"><?= $beOrdersOnly?'ORDER HISTORY':'A LITTLE CATCH-UP'; ?></span><h2><?= $beOrdersOnly?'Your orders':'Recent orders'; ?></h2></div><?php if(!$beOrdersOnly): ?><a class="be-textlink" href="<?= $beRoot.'/account/orders'; ?>">View all ↗</a><?php endif; ?></div>
<?php if(!empty($orders)): ?><div class="be-order-list"><?php foreach($orders as $o): ?><article class="be-account-order"><div><span class="be-order-reference">#<?= htmlspecialchars($o->order_code); ?></span><small><?= date('j M Y',strtotime($o->created_at ?? 'now')); ?></small></div><span class="be-order-status"><?= htmlspecialchars(ucfirst($o->order_status ?? 'pending')); ?></span><strong><?= sf_currency($o->grand_total,$store_currency ?? null); ?></strong></article><?php endforeach; ?></div><p class="be-account-note">For delivery updates, use your order reference and phone number on <a href="<?= $beRoot.'/track'; ?>">order tracking ↗</a>.</p><?php else: ?><div class="be-empty-state"><span aria-hidden="true">✳</span><h3><?= $beCopy('account_empty_heading'); ?></h3><p><?= $beCopy('account_empty_text'); ?></p><a class="be-pill" href="<?= $beRoot.'/products'; ?>"><?= $beCopy('shop_explore'); ?> ↗</a></div><?php endif; ?></section>
<?php if(!$beOrdersOnly): ?><?php foreach(['downloads'=>'Your downloads','courses'=>'Your courses','memberships'=>'Your memberships'] as $key=>$label):$bePurchases=${$key} ?? [];if(empty($bePurchases))continue; ?><section class="be-account-card"><div class="be-account-card-title"><h2><?= $label; ?></h2></div><?php foreach($bePurchases as $purchase): ?><div class="be-purchase-row"><div><strong><?= htmlspecialchars($purchase['name'] ?? ''); ?></strong><?php if(isset($purchase['progress'])): ?><p><?= (int)$purchase['progress']; ?>% complete</p><?php elseif(isset($purchase['status'])): ?><p><?= htmlspecialchars(ucfirst($purchase['status'])); ?></p><?php endif; ?></div><?php if(!empty($purchase['url'])): ?><a class="be-textlink" href="<?= htmlspecialchars($purchase['url']); ?>"><?= $key==='downloads'?'Download':'Continue'; ?> ↗</a><?php endif; ?></div><?php endforeach; ?></section><?php endforeach; ?><?php endif; ?>
</div></div>
</main>
